from taf.ue.rpc.mtk import mtk


class MessageProxy(object):

    _read_message_function_mapping = {"ota_text": "read_latest_ota_text_message",
                                      "ota_json": "read_latest_ota_json_message",
                                      "system_trace": "read_latest_system_trace",
                                      "ps_trace": "read_latest_ps_trace",
                                      "raw_string": "read_latest_raw_string"
                                      }

    def __init__(self, pyro_ip, pyro_port):
        self._mtk_rpc = mtk()
        self._mtk_rpc.configure(pyro_ip, pyro_port)

    def create_proxy(self, alias):
        self._mtk_rpc.create_proxy(alias)

    def read_latest_ota_text_message(self, alias):
        return self._mtk_rpc.read_latest_ota_message(proxy=alias)

    def read_latest_ota_json_message(self, alias):
        return self._mtk_rpc.read_latest_ota_message_details(proxy=alias)

    def read_latest_system_trace(self, alias):
        return self._mtk_rpc.read_latest_systrace(proxy=alias)

    def read_latest_ps_trace(self, alias, **kwargs):
        return self._mtk_rpc.read_latest_pstrace(proxy=alias, **kwargs)

    def read_latest_raw_string(self, alias, **kwargs):
        return self._mtk_rpc.read_latest_raw_string(proxy=alias, **kwargs)

    def get_read_message_function(self, message_type):
        return self.__getattribute__(self._read_message_function_mapping[message_type])
